 return{update(dt){const solo=c.players[0];c.hint('1P 방향: 줄 위 이동·바람 보정 / 팀 방향: 배 이동·A 대포');const q=c.input(solo,()=>({x:clamp(-solo.x*2-wind()*1.1,-1,1),z:-1}));solo.x+=q.x*1.25*dt+wind()*dt;solo.z=clamp(solo.z+q.z*1.15*dt,-6.5,6);solo.y=1.4;solo.pose='balance';for(const p of c.players.slice(1)){p.cool=Math.max(0,p.cool-dt);const side=p.i===1?-1:1;if(c.time>(p.nextAim||0)){p.nextAim=c.time+p.botLag;p.aimZ=solo.z+c.rand(-.6,.6);}const r=c.input(p,()=>({x:0,z:Math.abs(p.z-p.aimZ)>.2?Math.sign(p.aimZ-p.z):0,a:p.cool===0&&Math.abs(p.z-p.aimZ)<1}));p.x=clamp(p.x+r.x*2*dt,side<0?-6:-0+3,side<0?-3:6);p.z=clamp(p.z+r.z*2.4*dt,-6,6);p.y=0;if(r.ap&&p.cool===0){p.cool=1.25;bullets.push({id:id++,x:p.x,z:p.z,vx:-side*5,life:0});}}for(const b of bullets){b.x+=b.vx*dt;b.life+=dt;if(Math.hypot(b.x-solo.x,b.z-solo.z)<.52){solo.x+=Math.sign(b.vx)*.52;b.dead=true;}}for(let i=bullets.length-1;i>=0;i--)if(bullets[i].dead||bullets[i].life>3)bullets.splice(i,1);if(Math.abs(solo.x)>.8)lose('바람과 대포 때문에 줄에서 떨어졌습니다');else if(solo.z<=-6.3){solo.score=15;c.players.slice(1).forEach(p=>p.score=-5);c.complete([0],'줄을 끝까지 건넜습니다');}},render(){c.arena({width:16,depth:16,color:water});for(const z of [-7,7])c.draw('tower'+z,'box',{x:0,y:.55,z,sx:2,sy:1.1,sz:1.6,color:'#b9ae91'});c.draw('rope','box',{x:0,y:1.4,z:0,sx:.15,sy:.1,sz:13,color:'#e6d4a5'});c.players.slice(1).forEach(p=>{c.draw('boat'+p.i,'box',{x:p.x,y:-.05,z:p.z,sx:1.7,sy:.4,sz:2,color:'#a3bc91'});c.draw('cannon'+p.i,'cylinder',{x:p.x+(p.i===1?.5:-.5),y:.7,z:p.z,sx:.45,sy:1.3,sz:.45,rz:Math.PI/2,color:'#647f8c'});});bullets.forEach(b=>c.draw('ball'+b.id,'sphere',{x:b.x,y:1.65,z:b.z,sx:.4,sy:.4,sz:.4,color:'#667e8b'}));text(c,'wind',wind()>0?'바람 →':'← 바람',0,4,0,5);},timeout(){lose('시간 안에 줄을 건너지 못했습니다');}};
