 'Treasure Divers':treasure,'Skateboard Scamper':skateboard,'Platform Peril':platforms,'Mario Bandstand':band,'Key-pa-Way':keyAway,'Running of the Bulb':bulb,"Bash 'n' Cash":bash,'Bowl Over':bowl,'Coin Block Bash':blockBash,'Tightrope Treachery':tightrope,"Piranha's Pursuit":pursuit,'Coin Shower Flower':flower,'Bobsled Run':bobsled,'Desert Dash':desert,'Bombsketball':basketball,'Handcar Havoc':handcar,'Deep Sea Divers':divers,'Teetering Towers':towers,'Honeycomb Havoc':honeycomb,'Quick Draw Corks':corks
